function maxPoints(points: number[][]): number {
  const n = points.length;
  // Через одну или две точки всегда проходит прямая
  if (n <= 2) return n;

  // НОД по алгоритму Евклида
  const gcd = (a: number, b: number): number => (b === 0 ? a : gcd(b, a % b));

  let best = 0;
  for (let i = 0; i < n; i++) {
    // Для точки i: наклон -> сколько других точек лежат на прямой с этим наклоном через i
    const slopes = new Map<string, number>();
    let localBest = 0;

    for (let j = i + 1; j < n; j++) {
      let dx = points[j][0] - points[i][0];
      let dy = points[j][1] - points[i][1];

      // Сокращаем дробь dy/dx, чтобы одинаковые наклоны дали одинаковый ключ
      // (числа не делим — у double нет точного сравнения дробей)
      const g = gcd(Math.abs(dx), Math.abs(dy));
      dx /= g;
      dy /= g;

      // Нормализуем знак: dx > 0, а для вертикали (dx = 0) берём dy > 0
      if (dx < 0 || (dx === 0 && dy < 0)) {
        dx = -dx;
        dy = -dy;
      }

      const key = `${dy}/${dx}`;
      const count = (slopes.get(key) ?? 0) + 1;
      slopes.set(key, count);
      localBest = Math.max(localBest, count);
    }

    // +1 — сама точка i
    best = Math.max(best, localBest + 1);
  }

  return best;
}

// Время: O(n² · log C), где C — диапазон координат (на НОД)
// Память: O(n)
